345	            attributeSet.add(AttributeKey.valueOf(key));
346	        }
347	        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
348	            Set<AttributeKey> currentSet = this.attributes.get(tagName);
349	            currentSet.removeAll(attributeSet);
