374	
375	     @param tag   The tag the enforced attribute is for. The tag will be added to the allowed tag list if necessary.
376	     @param attribute   The attribute name
377	     @param value The enforced attribute value
378	     @return this (for chaining)
379	     */
380	    public Safelist addEnforcedAttribute(String tag, String attribute, String value) {
381	        Validate.notEmpty(tag);
382	        Validate.notEmpty(attribute);
383	        Validate.notEmpty(value);
384	
385	        TagName tagName = TagName.valueOf(tag);
386	        tagNames.add(tagName);
387	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
388	        AttributeValue attrVal = AttributeValue.valueOf(value);
389	
390	        Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
391	        attrMap.put(attrKey, attrVal);
392	        return this;
393	    }
394	
395	    /**
396	     Remove a previously configured enforced attribute from a tag.
397	
398	     @param tag   The tag the enforced attribute is for.
399	     @param attribute   The attribute name
400	     @return this (for chaining)
401	     */
402	    public Safelist removeEnforcedAttribute(String tag, String attribute) {
403	        Validate.notEmpty(tag);
404	        Validate.notEmpty(attribute);
405	
406	        TagName tagName = TagName.valueOf(tag);
407	        if(tagNames.contains(tagName) && enforcedAttributes.containsKey(tagName)) {
408	            AttributeKey attrKey = AttributeKey.valueOf(attribute);
409	            Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.get(tagName);
410	            attrMap.remove(attrKey);
411	
412	            if(attrMap.isEmpty()) // Remove tag from enforced attribute map if no enforced attributes are present
413	                enforcedAttributes.remove(tagName);
414	        }
415	        return this;
416	    }
417	
418	    /**
419	     * Configure this Safelist to preserve relative links in an element's URL attribute, or convert them to absolute
420	     * links. By default, this is <b>false</b>: URLs will be  made absolute (e.g. start with an allowed protocol, like
421	     * e.g. {@code http://}.
422	     *
423	     * @param preserve {@code true} to allow relative links, {@code false} (default) to deny
424	     * @return this Safelist, for chaining.
425	     * @see #addProtocols
426	     */
427	    public Safelist preserveRelativeLinks(boolean preserve) {
428	        preserveRelativeLinks = preserve;
429	        return this;
430	    }
431	
432	    /**
433	     * Get the current setting for preserving relative links.
434	     * @return {@code true} if relative links are preserved, {@code false} if they are converted to absolute.
435	     */
436	    public boolean preserveRelativeLinks() {
437	        return preserveRelativeLinks;
438	    }
439	
440	    /**
441	     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
442	     URLs with the defined protocol.
443	     <p>
444	     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
445	     </p>
446	     <p>
447	     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
448	     E.g.: <code>addProtocols("a", "href", "#")</code>
449	     </p>
450	
451	     @param tag       Tag the URL protocol is for
452	     @param attribute       Attribute name
453	     @param protocols List of valid protocols
454	     @return this, for chaining
455	     */
456	    public Safelist addProtocols(String tag, String attribute, String... protocols) {
457	        Validate.notEmpty(tag);
458	        Validate.notEmpty(attribute);
459	        Validate.notNull(protocols);
460	
461	        TagName tagName = TagName.valueOf(tag);
462	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
463	        Map<AttributeKey, Set<Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
464	        Set<Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());
465	
466	        for (String protocol : protocols) {
467	            Validate.notEmpty(protocol);
468	            Protocol prot = Protocol.valueOf(protocol);
469	            protSet.add(prot);
470	        }
471	        return this;
472	    }
473	
474	    /**
475	     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
476	     attribute will allow any protocol.
477	     <p>
478	     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
479	     </p>
480	
481	     @param tag Tag the URL protocol is for
482	     @param attribute Attribute name
483	     @param removeProtocols List of invalid protocols
484	     @return this, for chaining
485	     */
486	    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
487	        Validate.notEmpty(tag);
488	        Validate.notEmpty(attribute);
489	        Validate.notNull(removeProtocols);
490	
491	        TagName tagName = TagName.valueOf(tag);
492	        AttributeKey attr = AttributeKey.valueOf(attribute);
493	
494	        // make sure that what we're removing actually exists; otherwise can open the tag to any data and that can
495	        // be surprising
496	        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
497	        Map<AttributeKey, Set<Protocol>> tagProtocols = protocols.get(tagName);
498	        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");
499	
500	        Set<Protocol> attrProtocols = tagProtocols.get(attr);
501	        for (String protocol : removeProtocols) {
502	            Validate.notEmpty(protocol);
503	            attrProtocols.remove(Protocol.valueOf(protocol));
504	        }
505	
506	        if (attrProtocols.isEmpty()) { // Remove protocol set if empty
507	            tagProtocols.remove(attr);
508	            if (tagProtocols.isEmpty()) // Remove entry for tag if empty
509	                protocols.remove(tagName);
510	        }
511	        return this;
512	    }
513	
514	    /**
515	     * Test if the supplied tag is allowed by this safelist.
516	     * @param tag test tag
517	     * @return true if allowed
518	     */
519	    public boolean isSafeTag(String tag) {
520	        return tagNames.contains(TagName.valueOf(tag));
521	    }
522	
523	    /**
524	     * Test if the supplied attribute is allowed by this safelist for this tag.
525	     * <p>This method does not modify the input element or attribute.</p>
526	     * @param tagName tag to consider allowing the attribute in
527	     * @param el element under test, to confirm protocol
528	     * @param attr attribute under test
529	     * @return true if allowed
530	     */
531	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
532	        TagName tag = TagName.valueOf(tagName);
533	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
534	
535	        Set<AttributeKey> okSet = attributes.get(tag);
536	        if (okSet != null && okSet.contains(key)) {
537	            if (protocols.containsKey(tag)) {
538	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
539	                // ok if not defined protocol; otherwise test
540	                return !attrProts.containsKey(key) || isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key));
541	            } else { // attribute found, no protocols defined, so OK
542	                return true;
543	            }
544	        }
545	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
546	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
547	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
548	            // if the input already has that exact value, treat it as safe
549	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
550	        }
551	        // no attributes defined for tag, try :all tag
552	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
553	    }
554	
555	    private String getProtocolValue(Element el, Attribute attr) {
556	        String value = el.absUrl(attr.getKey());
557	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
558	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
559	        return value;
560	    }
561	
562	    /**
563	     Test if the supplied attribute is structurally allowed on this tag by the safelist, without applying the
564	     whole-value protocol check. This is used for attributes whose value is validated piece by piece by the
565	     {@link Cleaner} (currently {@code srcset}, whose individual candidate URLs are checked separately); ordinary
566	     attributes use {@link #isSafeAttribute(String, Element, Attribute)}.
567	     @param tagName tag to consider allowing the attribute in
568	     @param el element under test
569	     @param attr attribute under test
570	     @return true if the attribute is allowed by the tag/attribute configuration, regardless of its value
571	     */
572	    boolean isAllowedAttribute(String tagName, Element el, Attribute attr) {
573	        TagName tag = TagName.valueOf(tagName);
574	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
575	
576	        Set<AttributeKey> okSet = attributes.get(tag);
577	        if (okSet != null && okSet.contains(key)) return true;
578	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
579	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
580	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
581	        }
582	        return !tagName.equals(All) && isAllowedAttribute(All, el, attr);
583	    }
584	
585	    /**
586	     Get the allowed protocol set that governs the individual URLs inside a {@code srcset} attribute on the given
587	     tag. Because a {@code srcset} value carries multiple candidate URLs, each one is checked against the same
588	     protocol policy as an ordinary URI attribute: an explicit {@code srcset} policy wins, otherwise the tag's
589	     {@code src} policy applies. A {@code source} element inside a {@code picture} is an alternative to the
590	     fallback {@code img}, so a {@code source} with no policy of its own is then judged by the {@code img} tag's
591	     {@code srcset}/{@code src} policy; this keeps a {@code source} srcset and the fallback {@code img} srcset in
592	     the same picture under identical candidate rules. Resolution finally falls back to the {@code :all} tag in the
593	     same order.
594	     @param tagName the tag carrying the srcset attribute
595	     @return the allowed protocols (never null; an empty set means no protocol restriction applies)
596	     */
597	    Set<Protocol> srcsetProtocols(String tagName) {
598	        TagName tag = TagName.valueOf(tagName);
599	        AttributeKey srcset = AttributeKey.valueOf("srcset");
600	        AttributeKey src = AttributeKey.valueOf("src");
601	
602	        Set<Protocol> allowed = protocolsFor(tag, srcset);
603	        if (allowed == null) allowed = protocolsFor(tag, src);
604	        if (allowed == null && tag.equals(SourceTag)) {
605	            // no policy of the <source>'s own: apply the fallback <img> policy so that candidates are filtered
606	            // identically on the source and the img within one picture
607	            allowed = protocolsFor(ImgTag, srcset);
608	            if (allowed == null) allowed = protocolsFor(ImgTag, src);
609	        }
610	        if (allowed == null && !tag.equals(AllTag)) {
611	            allowed = protocolsFor(AllTag, srcset);
612	            if (allowed == null) allowed = protocolsFor(AllTag, src);
613	        }
614	        return allowed == null ? Collections.emptySet() : allowed;
615	    }
616	
617	    private static final TagName ImgTag = TagName.valueOf("img");
618	    private static final TagName SourceTag = TagName.valueOf("source");
619	
620	    private Set<Protocol> protocolsFor(TagName tag, AttributeKey key) {
621	        Map<AttributeKey, Set<Protocol>> byAttribute = protocols.get(tag);
622	        return byAttribute == null ? null : byAttribute.get(key);
623	    }
624	
625	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
626	        for (Protocol protocol : protocols) {
627	            String prot = protocol.toString();
628	
629	            if (prot.equals("#")) { // allows anchor links
630	                if (isValidAnchor(value)) {
631	                    return true;
632	                } else {
633	                    continue;
634	                }
635	            }
636	
637	            String lc = lowerCase(value);
638	            if (lc.startsWith(prot)
639	                && lc.length() > prot.length()
640	                && lc.charAt(prot.length()) == ':') {
641	                return true;
642	            }
643	        }
644	        return false;
645	    }
646	
647	    /**
648	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
649	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
650	     attribute.
651	     */
652	    boolean shouldAbsUrl(String tagName, String attrKey) {
653	        if (preserveRelativeLinks) return false;
654	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
655	    }
656	
657	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
658	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
659	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
660	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
661	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
662	        }
663	
664	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
665	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
666	
667	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
668	    }
669	
670	    private static boolean isValidAnchor(String value) {
671	        return value.startsWith("#") && !value.matches(".*\\s.*");
672	    }
673	
674	    /**
675	     Gets the Attributes that should be enforced for a given tag
676	     * @param tagName the tag
677	     * @return the attributes that will be enforced; empty if none are set for the given tag
678	     */
679	    public Attributes getEnforcedAttributes(String tagName) {
680	        Attributes attrs = new Attributes();
681	        TagName tag = TagName.valueOf(tagName);
682	        if (enforcedAttributes.containsKey(tag)) {
683	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
684	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
685	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
686	            }
687	        }
688	        return attrs;
689	    }
690	    
691	    // named types for config. All just hold strings, but here for my sanity.
692	
693	    static class TagName extends TypedValue {
694	        TagName(String value) {
695	            super(value);
696	        }
697	
698	        static TagName valueOf(String value) {
699	            return new TagName(Normalizer.lowerCase(value));
700	        }
701	    }
702	
703	    static class AttributeKey extends TypedValue {
704	        AttributeKey(String value) {
705	            super(value);
706	        }
707	
708	        static AttributeKey valueOf(String value) {
709	            return new AttributeKey(Normalizer.lowerCase(value));
710	        }
711	    }
712	
713	    static class AttributeValue extends TypedValue {
714	        AttributeValue(String value) {
715	            super(value);
716	        }
717	
718	        static AttributeValue valueOf(String value) {
719	            return new AttributeValue(value);
720	        }
721	    }
722	
723	    static class Protocol extends TypedValue {
724	        Protocol(String value) {
725	            super(value);
726	        }
727	
728	        static Protocol valueOf(String value) {
729	            return new Protocol(value);
730	        }
731	    }
732	
733	    abstract static class TypedValue {
734	        private final String value;
735	
736	        TypedValue(String value) {
737	            Validate.notNull(value);
738	            this.value = value;
739	        }
740	
741	        @Override
742	        public int hashCode() {
743	            return value.hashCode();
744	        }
745	
746	        @Override
747	        public boolean equals(Object obj) {
748	            if (this == obj) return true;
749	            if (obj == null || getClass() != obj.getClass()) return false;
750	            TypedValue other = (TypedValue) obj;
751	            return Objects.equals(value, other.value);
752	        }
753	
754	        @Override
755	        public String toString() {
756	            return value;
757	        }
758	    }
759	}
