201	    /**
202	     * Tests if a code point is "whitespace" as defined by what it looks like. Used for Element.text etc.
203	     * @param c code point to test
204	     * @return true if code point is whitespace, false otherwise
205	     */
206	    public static boolean isActuallyWhitespace(int c){
207	        return c == ' ' || c == '\t' || c == '\n' || c == '\f' || c == '\r' || c == 160;
208	        // 160 is &nbsp; (non-breaking space). Not in the spec but expected.
209	    }
