216	    /**
217	     * Normalise the whitespace within this string; multiple spaces collapse to a single, and all whitespace characters
218	     * (e.g. newline, tab) convert to a simple space.
219	     * @param string content to normalise
220	     * @return normalised string
221	     */
222	    public static String normaliseWhitespace(String string) {
223	        StringBuilder sb = StringUtil.borrowBuilder();
224	        appendNormalisedWhitespace(sb, string, false);
225	        return StringUtil.releaseBuilder(sb);
226	    }
