228	    /**
229	     * After normalizing the whitespace within a string, appends it to a string builder.
230	     * @param accum builder to append to
231	     * @param string string to normalize whitespace within
232	     * @param stripLeading set to true if you wish to remove any leading whitespace
233	     */
234	    public static void appendNormalisedWhitespace(StringBuilder accum, String string, boolean stripLeading) {
235	        boolean lastWasWhite = false;
236	        boolean reachedNonWhite = false;
237	
238	        int len = string.length();
239	        int c;
240	        for (int i = 0; i < len; i+= Character.charCount(c)) {
241	            c = string.codePointAt(i);
242	            if (isActuallyWhitespace(c)) {
243	                if ((stripLeading && !reachedNonWhite) || lastWasWhite)
244	                    continue;
245	                accum.append(' ');
246	                lastWasWhite = true;
247	            }
248	            else if (!isInvisibleChar(c)) {
249	                accum.appendCodePoint(c);
250	                lastWasWhite = false;
251	                reachedNonWhite = true;
252	            }
253	        }
254	    }
