293	    /**
294	     * Create a new absolute URL, from a provided existing absolute URL and a relative URL component.
295	     * @param base the existing absolute base URL
296	     * @param relUrl the relative URL to resolve. (If it's already absolute, it will be returned)
297	     * @return the resolved absolute URL
298	     * @throws MalformedURLException if an error occurred generating the URL
299	     */
300	    public static URL resolve(URL base, String relUrl) throws MalformedURLException {
301	        relUrl = stripControlChars(relUrl);
302	        // workaround: java resolves '//path/file + ?foo' to '//path/?foo', not '//path/file?foo' as desired
303	        if (relUrl.startsWith("?"))
304	            relUrl = base.getPath() + relUrl;
305	        // workaround: //example.com + ./foo = //example.com/./foo, not //example.com/foo
306	        URL url = new URL(base, relUrl);
307	        String fixedFile = extraDotSegmentsPattern.matcher(url.getFile()).replaceFirst("/");
308	        if (url.getRef() != null) {
309	            fixedFile = fixedFile + "#" + url.getRef();
310	        }
311	        URL resolved = new URL(url.getProtocol(), url.getHost(), url.getPort(), fixedFile);
312	        validateHttpUrl(resolved);
313	        return resolved;
314	    }
