316	    /**
317	     * Create a new absolute URL, from a provided existing absolute URL and a relative URL component.
318	     * @param baseUrl the existing absolute base URL
319	     * @param relUrl the relative URL to resolve. (If it's already absolute, it will be returned)
320	     * @return an absolute URL if one was able to be generated, or the empty string if not
321	     */
322	    public static String resolve(String baseUrl, String relUrl) {
323	        // workaround: java will allow control chars in a path URL and may treat as relative, but Chrome / Firefox will strip and may see as a scheme. Normalize to browser's view.
324	        baseUrl = stripControlChars(baseUrl); relUrl = stripControlChars(relUrl);
325	        try {
326	            URL base = new URL(baseUrl);
327	            return resolve(base, relUrl).toExternalForm();
328	        } catch (MalformedURLException e) {
329	            try {
330	                // the base is unsuitable, or resolution failed; the attribute/rel may be abs on its own
331	                URL abs = new URL(relUrl);
332	                validateHttpUrl(abs);
333	                return abs.toExternalForm();
334	            } catch (MalformedURLException ignored) {
335	                // it may still be valid, just that Java doesn't have a registered stream handler for it, e.g. tel
336	                // we test here vs at start to normalize supported URLs (e.g. HTTP -> http)
337	                return validUriScheme.matcher(relUrl).find() && !hasHttpScheme(relUrl) ? relUrl : "";
338	            }
339	        }
340	    }
341	    private static final Pattern validUriScheme = Pattern.compile("^[a-zA-Z][a-zA-Z0-9+-.]*:");
