343	    /** Validates that an HTTP(S) URL has the host required by its scheme. */
344	    private static void validateHttpUrl(URL url) throws MalformedURLException {
345	        if (isHttpScheme(url.getProtocol()) && url.getHost().isEmpty())
346	            throw new MalformedURLException("Invalid URL: host is missing");
347	    }
