360	    private static final Pattern controlChars = Pattern.compile("[\\x00-\\x1f]*"); // matches ascii 0 - 31, to strip from url
361	    private static String stripControlChars(final String input) {
362	        return controlChars.matcher(input).replaceAll("");
363	    }
